/* Persistent draft-map workspace. Province summaries only: no invented area geometry. */
(function(global){
 'use strict';
 let layer='eligible',province='',selectedArea='',tab='demand',view='0 0 640 900',context='',pan=null;
 const labels={eligible:['ผ่านเกณฑ์','Qualifying'],added:['เข้าใหม่','Newly qualify'],removed:['หลุดเกณฑ์','No longer qualify'],review:['รอตรวจ','Review'],rank:['อันดับ','Ranking']};
 const esc=s=>escapeHTML(s),icon=n=>global.YolkIcons?.icon(n)||'';
 function snapshot(oldRows,nextRows){
  const old=oldRows.filter(a=>a.eligible),next=nextRows.filter(a=>a.eligible),oldIDs=new Set(old.map(a=>a.id)),nextIDs=new Set(next.map(a=>a.id)),ranks=new Map(old.map((a,i)=>[a.id,i+1]));
  return {old,next,oldIDs,nextIDs,ranks,added:next.filter(a=>!oldIDs.has(a.id)),removed:old.filter(a=>!nextIDs.has(a.id)),review:nextRows.filter(a=>a.reviewCandidate),moved:next.filter((a,i)=>ranks.has(a.id)&&ranks.get(a.id)!==i+1),nextRows};
 }
 function getState(){return snapshot(evaluate(Y.criteria),evaluate(draft))}
 function rowsFor(s){return layer==='added'?s.added:layer==='removed'?s.removed:layer==='review'?s.review:layer==='rank'?s.moved:s.next}
 function shell(){return `<section class="criteria-map-panel" aria-labelledby="draft-map-title"><div class="draft-map-heading"><div><h2 id="draft-map-title">${global.YolkIcons?.demandIcon()||''}${tr('ปรับแล้ว ที่ไหนเปลี่ยน','See what changes.')}</h2><span>${tr('แบบร่างเทียบเกณฑ์ทีม','Draft vs. team criteria')} v${Y.criteria.version}</span></div><button class="btn small-button draft-expand" data-criteria-map="expand" aria-pressed="false">${icon('map')}${tr('ขยายพื้นที่ทำงาน','Expand workspace')}</button><button class="btn small-button" data-criteria-map="home" aria-label="${tr('แสดงทั้งประเทศ','Show nationwide')}">${icon('map')}${tr('ทั้งประเทศ','Nationwide')}</button></div><div id="draft-map-stats" class="draft-map-stats" role="status" aria-live="polite"></div><div class="draft-map-layers" role="group" aria-label="${tr('มุมมองผลบนแผนที่','Map result view')}">${Object.entries(labels).map(([key,text])=>`<button type="button" data-criteria-layer="${key}" aria-pressed="${layer===key}">${icon(key==='review'?'fact_check':key==='rank'?'tune':'location_on')}${tr(...text)}</button>`).join('')}</div><div class="draft-map-stage"><svg id="criteria-map-svg" viewBox="${view}" role="group" aria-label="${tr('แผนที่สรุปผลเกณฑ์รายจังหวัด กดจังหวัดเพื่อดูทำเล','Criteria results by province. Select a province to see locations.')}"><defs><pattern id="draft-missing" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="7" height="7" fill="var(--yl-no-data)"/><path d="M0 7 7 0" stroke="var(--line)"/></pattern></defs><g id="draft-map-paths"></g><g id="draft-map-badges" pointer-events="none"></g></svg><div class="draft-map-tools"><button type="button" data-criteria-map="in" aria-label="${tr('ซูมเข้า','Zoom in')}">+</button><button type="button" data-criteria-map="out" aria-label="${tr('ซูมออก','Zoom out')}">−</button></div><button type="button" class="draft-mobile-results" data-criteria-map="results" aria-expanded="false">${icon('fact_check')}${tr('ทำเล','Locations')}</button><section class="draft-map-results"><label class="draft-province-filter"><span>${tr('ดูจังหวัด','Province')}</span><select id="criteria-province-select" aria-label="${tr('กรองจังหวัดในแผนที่','Filter map by province')}"><option value="">${tr('ทั่วประเทศ','Nationwide')}</option>${P.map(p=>`<option value="${p.code}" ${province===p.code?'selected':''}>${esc(provinceName(p.code))}</option>`).join('')}</select></label><div class="draft-results-heading"><h3 id="draft-results-title"></h3><button type="button" data-criteria-map="clear" aria-label="${tr('ล้างจังหวัดที่เลือก','Clear province selection')}">${icon('close')}</button></div><div id="draft-area-inspector" hidden></div><div id="draft-results-list"></div></section></div><div id="draft-map-legend" class="draft-map-legend"></div><p class="draft-map-credit">${tr('ขอบเขตจังหวัด: OSM / geoBoundaries · จุดตัวเลขสรุปจำนวนทำเล ไม่ใช่พิกัดสาขา','Province boundaries: OSM / geoBoundaries · Number badges summarize areas, not branch coordinates')} · © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> / geoBoundaries · ODbL · 2017</p></section>`}
 function sync(){
  const panel=document.querySelector('.criteria-map-panel');if(!panel)return;
  const key=criteriaContextKey();if(context!==key){context=key;province='';selectedArea='';view='0 0 640 900';layer='eligible'}
  panel.removeAttribute('aria-busy');const errors=criteriaErrors(draft);
  document.querySelectorAll('[data-criteria-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.criteriaLayer===layer)));
  if(errors.length){const inspector=document.querySelector('#draft-area-inspector');inspector.hidden=true;inspector.innerHTML='';document.querySelector('#draft-map-stats').innerHTML=`<p role="alert">${tr('ค่าบางข้อยังไม่ครบ แผนที่พักผลไว้ก่อน ตรวจช่องที่กำลังปรับแล้วลองใหม่','Some settings are incomplete. Map results are paused; check the fields you are editing.')}</p>`;document.querySelector('#draft-map-paths').innerHTML='';document.querySelector('#draft-map-badges').innerHTML='';document.querySelector('#draft-results-list').innerHTML='';document.querySelector('#criteria-province-select').value=province;document.querySelector('#draft-results-title').textContent=tr('รอเกณฑ์ที่ถูกต้อง','Awaiting valid settings');document.querySelector('#draft-map-legend').textContent=tr('ไม่แสดงผลเดิมเป็นผลของค่าที่ไม่ถูกต้อง','Previous results are not shown as results of invalid settings');return}
  const s=getState(),rows=rowsFor(s),byProvince=new Map(P.map(p=>[p.code,[]]));rows.forEach(a=>byProvince.get(a.province)?.push(a));
  document.querySelector('#draft-map-stats').innerHTML=`<div><span>${tr('ผ่านเกณฑ์ทีม → แบบร่าง','Team → draft matches')}</span><strong>${num(s.old.length)} → ${num(s.next.length)}</strong></div><div><span>${tr('เข้าใหม่ / หลุดเกณฑ์','New / removed')}</span><strong>+${num(s.added.length)} / −${num(s.removed.length)}</strong></div><div><span>${tr('ทำเลเดิมอันดับเปลี่ยน','Existing ranks changed')}</span><strong>${num(s.moved.length)}</strong></div>`;
  const summary=p=>{const count=byProvince.get(p.code).length,added=s.added.filter(a=>a.province===p.code).length,removed=s.removed.filter(a=>a.province===p.code).length;return `${provinceName(p.code)} · ${tr(...labels[layer])} ${num(count)} · +${num(added)} / −${num(removed)}`};
  document.querySelector('#draft-map-paths').innerHTML=P.map(p=>{const list=byProvince.get(p.code),high=list.filter(a=>a.demand===true),best=high.length?Math.max(...high.map(a=>a.score)):null;const fill=layer==='review'&&list.length?'url(#draft-missing)':layer==='rank'||best===null?'var(--no-result)':`var(--yl-yolk-map-${best>=99?3:best>=95?2:1})`;return `<path class="draft-province ${province===p.code?'is-selected':''}" data-criteria-province="${p.code}" d="${p.path}" fill="${fill}" fill-rule="evenodd" role="button" tabindex="0" aria-label="${esc(summary(p))}"><title>${esc(summary(p))}</title></path>`}).join('');
  const svg=document.querySelector('#criteria-map-svg'),box=svg.getBoundingClientRect(),vb=view.split(' ').map(Number),unit=Math.max(vb[2]/box.width,vb[3]/box.height),occupied=[];
  const badgeProvinces=P.filter(p=>byProvince.get(p.code).length).sort((a,b)=>(a.code===province?-1:b.code===province?1:byProvince.get(b.code).length-byProvince.get(a.code).length));
  document.querySelector('#draft-map-badges').innerHTML=badgeProvinces.map(p=>{const [x,y]=p.centroid;if(x<vb[0]||x>vb[0]+vb[2]||y<vb[1]||y>vb[1]+vb[3])return '';if(occupied.some(([ox,oy])=>Math.abs(x-ox)<42*unit&&Math.abs(y-oy)<26*unit))return '';occupied.push([x,y]);const count=byProvince.get(p.code).length;return `<g transform="translate(${x} ${y}) scale(${unit})"><rect x="-21" y="-11" width="42" height="22" rx="7"/><text text-anchor="middle" y="4">${layer==='added'?'+':layer==='removed'?'−':layer==='rank'?'↕':''}${count}</text></g>`}).join('');
  const inspector=document.querySelector('#draft-area-inspector'),selected=s.nextRows.find(a=>a.id===selectedArea);inspector.hidden=!selected;inspector.innerHTML=selected?`<strong>${esc(areaName(selected.id))}</strong><span>${selected.eligible?tr('ผ่านเกณฑ์แบบร่าง','Qualifies under draft'):selected.reviewCandidate?tr('รอตรวจข้อมูล','Needs evidence review'):tr('ไม่ผ่านแบบร่าง','Outside draft criteria')} · ${YolkDecisions.tierText(selected)}</span><span>${tr('เรา','Own')} ${supplyCountText(selected.supply,'own')} · ${tr('คู่แข่ง','Others')} ${supplyCountText(selected.supply,'competitor')}</span><button class="quiet-link" data-action="place" data-id="${selected.id}">${tr('เปิดรายละเอียดตามเกณฑ์ทีม','Open detail with team criteria')} →</button>`:'';
  const filtered=province?rows.filter(a=>a.province===province):rows,rankMap=new Map(s.next.map((a,i)=>[a.id,i+1]));
  document.querySelector('#criteria-province-select').value=province;document.querySelector('#draft-results-title').textContent=(province?provinceName(province):tr('ทั่วประเทศ','Nationwide'))+' · '+num(filtered.length)+' '+tr(...labels[layer]);
  document.querySelector('[data-criteria-map="clear"]').hidden=!province;
  document.querySelector('#draft-results-list').innerHTML=filtered.length?filtered.slice(0,30).map(a=>{const oldRank=s.ranks.get(a.id),newRank=rankMap.get(a.id);return `<button type="button" class="draft-area-result" data-criteria-area="${a.id}"><span><strong>${esc(areaName(a.id))}</strong><small>${esc(provinceName(a.province))} · ${YolkDecisions.tierText(a)}</small></span><b>${layer==='rank'?`${oldRank||'—'} → ${newRank||'—'}`:layer==='added'?'+':layer==='removed'?'−':a.qualifyingTier?'T'+a.qualifyingTier:'?'}</b></button>`}).join('')+(filtered.length>30?`<p class="draft-list-note">${tr('แสดง 30 ทำเลแรกจาก ','First 30 of ')}${num(filtered.length)} · ${tr('เลือกจังหวัดเพื่อเจาะดู','Select a province to narrow the list')}</p>`:''):`<p class="draft-list-note">${tr('ไม่มีทำเลในมุมมองนี้ ลองเลือกจังหวัดอื่นหรือปรับเกณฑ์','No locations in this view. Try another province or adjust criteria.')}</p>`;
  document.querySelector('#draft-map-legend').innerHTML=layer==='rank'?tr('↕ จำนวนทำเลที่อันดับเปลี่ยน · รายการแสดงอันดับทีม → แบบร่าง','↕ Locations with changed ranks · List shows team → draft rank'):layer==='review'?tr('ลายเฉียง = มีทำเลรอตรวจ · ยังไม่รวมในจำนวนผ่านยืนยัน','Hatching = locations needing review, excluded from confirmed matches'):`<span><i style="background:var(--yl-yolk-map-1)"></i>< P95</span><span><i style="background:var(--yl-yolk-map-2)"></i>P95–<99</span><span><i style="background:var(--yl-yolk-map-3)"></i>P99–100</span><span>${tr('สี: Demand เด่นสุดในกลุ่มที่แสดง · ตัวเลข: จำนวนทำเล','Color: strongest Demand signal in shown areas · Badges: area counts')}</span>`;
  document.querySelector('#criteria-map-svg').setAttribute('viewBox',view);
 }
 function activateTab(id){if(!['demand','supply','strategy'].includes(id))id='demand';if(tab!==id){const scroller=document.querySelector('.criteria-control-scroll');if(scroller)scroller.scrollTop=0}tab=id;document.querySelectorAll('[data-criteria-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.criteriaTab===tab));b.tabIndex=b.dataset.criteriaTab===tab?0:-1});document.querySelectorAll('[data-criteria-pane]').forEach(p=>p.hidden=p.dataset.criteriaPane!==tab);}
 function fit(){const workspace=document.querySelector('.criteria-live-workspace');if(workspace&&innerWidth>=1000)workspace.style.height=Math.max(340,innerHeight-workspace.getBoundingClientRect().top-(innerWidth<1100?132:64))+'px'}
 function mount(){if(!document.querySelector('.criteria-map-panel'))return;activateTab(tab);sync();fit()}
 global.addEventListener('resize',()=>{const workspace=document.querySelector('.criteria-live-workspace.is-expanded');if(workspace&&innerWidth<1000){workspace.classList.remove('is-expanded');['role','aria-modal','aria-label'].forEach(name=>workspace.removeAttribute(name));const button=workspace.querySelector('[data-criteria-map=expand]');button.setAttribute('aria-pressed','false');button.innerHTML=icon('map')+tr('ขยายพื้นที่ทำงาน','Expand workspace')}fit();if(document.querySelector('.criteria-map-panel'))sync()});document.addEventListener('toggle',e=>{if(e.target.matches('.workspace-context-disclosure'))fit()},true)
 function pending(){const panel=document.querySelector('.criteria-map-panel');if(panel)panel.setAttribute('aria-busy','true')}
 function zoom(factor){const b=view.split(' ').map(Number),w=Math.min(1280,Math.max(60,b[2]*factor)),h=w*900/640;view=`${b[0]+(b[2]-w)/2} ${b[1]+(b[3]-h)/2} ${w} ${h}`;sync()}
 document.addEventListener('click',e=>{const t=e.target.closest('[data-criteria-tab],[data-criteria-layer],[data-criteria-province],[data-criteria-map],[data-criteria-area]');if(!t)return;if(t.dataset.criteriaArea){selectedArea=t.dataset.criteriaArea;const area=AREAS.find(a=>a.id===selectedArea);if(area)province=area.province;sync();return}if(t.dataset.criteriaTab){activateTab(t.dataset.criteriaTab);return}if(t.dataset.criteriaLayer){layer=t.dataset.criteriaLayer;sync();return}if(t.dataset.criteriaProvince){province=t.dataset.criteriaProvince;const b=t.getBBox(),pad=Math.max(b.width,b.height)*.15;const w=Math.max(70,b.width+2*pad,(b.height+2*pad)*640/900),h=w*900/640;view=`${b.x+b.width/2-w/2} ${b.y+b.height/2-h/2} ${w} ${h}`;sync();return}const action=t.dataset.criteriaMap;if(action==='expand'){const workspace=document.querySelector('.criteria-live-workspace'),expanded=workspace.classList.toggle('is-expanded');t.setAttribute('aria-pressed',String(expanded));if(expanded){workspace.setAttribute('role','dialog');workspace.setAttribute('aria-modal','true');workspace.setAttribute('aria-label',tr('พื้นที่ปรับเกณฑ์และแผนที่','Criteria and map workspace'))}else{workspace.removeAttribute('role');workspace.removeAttribute('aria-modal');workspace.removeAttribute('aria-label')}t.innerHTML=icon('map')+tr(expanded?'กลับหน้าปกติ':'ขยายพื้นที่ทำงาน',expanded?'Exit expanded view':'Expand workspace');sync();return}if(action==='results'){const stage=t.closest('.draft-map-stage'),open=stage.classList.toggle('is-results-open');t.setAttribute('aria-expanded',String(open));return}if(action==='home'){province='';selectedArea='';view='0 0 640 900';sync()}if(action==='clear'){province='';sync()}if(action==='in'||action==='out')zoom(action==='in'?.7:1/.7)});
 document.addEventListener('change',e=>{if(e.target.id!=='criteria-province-select')return;province=e.target.value;if(province){const path=document.querySelector(`[data-criteria-province="${province}"]`);if(!path){sync();return}const b=path.getBBox(),w=Math.max(70,b.width*1.3,b.height*1.3*640/900);view=`${b.x+b.width/2-w/2} ${b.y+b.height/2-w*900/1280} ${w} ${w*900/640}`}else view='0 0 640 900';sync()});
 document.addEventListener('keydown',e=>{const expandedWorkspace=document.querySelector('.criteria-live-workspace.is-expanded');if(e.key==='Tab'&&expandedWorkspace){const focusables=[...expandedWorkspace.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),summary,a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length&&el.tabIndex>=0&&!el.closest('fieldset[disabled]')),first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(e.key==='Escape'&&document.querySelector('.criteria-live-workspace.is-expanded')){document.querySelector('[data-criteria-map=expand]').click();document.querySelector('[data-criteria-map=expand]').focus();return}if(e.target.matches('[data-criteria-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-criteria-tab]')],i=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();return}if(e.target.matches('[data-criteria-province]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
 document.addEventListener('pointerdown',e=>{const svg=e.target.closest('#criteria-map-svg');if(!svg||e.button!==0)return;pan={svg,x:e.clientX,y:e.clientY,view:view.split(' ').map(Number),moved:false,pointerId:e.pointerId}});
 document.addEventListener('pointermove',e=>{if(!pan)return;const dx=e.clientX-pan.x,dy=e.clientY-pan.y;if(Math.abs(dx)+Math.abs(dy)<5)return;if(!pan.moved)pan.svg.setPointerCapture(pan.pointerId);pan.moved=true;const rect=pan.svg.getBoundingClientRect(),scale=Math.min(rect.width/pan.view[2],rect.height/pan.view[3]);view=`${pan.view[0]-dx/scale} ${pan.view[1]-dy/scale} ${pan.view[2]} ${pan.view[3]}`;pan.svg.setAttribute('viewBox',view)});
 document.addEventListener('pointercancel',()=>{pan=null});
 document.addEventListener('pointerup',e=>{if(pan?.moved){const svg=pan.svg;svg.addEventListener('click',event=>event.stopPropagation(),{once:true,capture:true});pan=null;sync();return}pan=null});
 global.YolkCriteriaMap={shell,mount,mountControls(){activateTab(tab)},sync,pending,snapshot,showRanking(){layer='rank';global.YolkWorkspaceMap?.setLayer('rank')}};
})(window);
